steps.script:
var d = tree.root.get_node("/root/AttackAssignmentDialog")
if d._groups.size() != 1:
	return "expected ONE section, got %d" % d._groups.size()
return "%s x%d weapons=%d" % [str(d._groups[0].label), (d._groups[0].models as Array).size(), (d._groups[0].weapons as Array).size()]

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append("%s:%d" % [str(a.get("target", "?")), (a.get("models", []) as Array).size()])
out.sort()
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var seen = {}
for a in d.assignments:
	for m in a.get("models", []):
		if seen.has(str(m)):
			return "model " + str(m) + " assigned twice"
		seen[str(m)] = true
return str(seen.size())

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var sb = d.get_node_or_null("Content/GroupsScroll/GroupsBox/Group0/Body/SplitBox")
if sb == null:
	return "no SplitBox"
var rows = []
for c in sb.get_children():
	rows.append(c.name)
return "vis=%s %s" % [str(sb.visible), ",".join(rows)]

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var a = d.get_node("Content/GroupsScroll/GroupsBox/Group0/Body/SplitBox/SplitRow_guardian_spear_melee/LineTarget_guardian_spear_melee")
var b = d.get_node("Content/GroupsScroll/GroupsBox/Group0/Body/SplitBox/SplitRow_guardian_spear_melee_2/LineTarget_guardian_spear_melee_2")
return "%s | %s" % [str(a.text), str(b.text)]

var d = tree.root.get_node("/root/AttackAssignmentDialog")
for i in range(d.target_list.item_count):
	if str(d.target_list.get_item_metadata(i)) == "U_WARBOSS_B":
		d.target_list.select(i)
		return "selected"
return "Warboss not in target list"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append("%s:%d" % [str(a.get("target", "?")), (a.get("models", []) as Array).size()])
out.sort()
return ",".join(out)

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var t = str(d.assignments_display.get_parsed_text())
if not "Overkill" in t:
	return "no overkill warning in: " + t
if not "Warboss" in t:
	return "warning does not name the target: " + t
if not "thrown away" in t:
	return "no wasted-damage figure: " + t
return "warned"

var d = tree.root.get_node("/root/AttackAssignmentDialog")
var out = []
for a in d.assignments:
	out.append("%s:%d" % [str(a.get("target", "?")), (a.get("models", []) as Array).size()])
out.sort()
return ",".join(out)

var p = PhaseManager.get_current_phase_instance()
var out = []
for a in p.staged_fight_state["assignments"]:
	out.append("%s:%d" % [str(a.get("target", "?")), (a.get("models", []) as Array).size()])
out.sort()
return ",".join(out)
